namespace CET6Word {
 public partial class DesktopUI {
  Grid studyGrid;Grid studyColumns;Border searchPanel;ColumnDefinition searchColumn;ContentControl studyBody;StackPanel studyFooter;WordPage studyPage;
  string bookMode="",selectedBook="default";ContentControl bookBody;StackPanel bookFooter;WordPage bookPage;
  ReadingPosition StudyPosition {get{return engine.ReadingAt(LearningEngine.StudyKey(engine.Current.Id,engine.Position.Mode));}}
  WordView View(Word word,string context){return new WordView{Word=word,Engine=engine,Context=context,Global=context!="study"||engine.State.Settings.Translation,Level=context=="study"?(expansion.ContainsKey(word.Id)?expansion[word.Id]:0):1};}
  void ShowStudy(){EnterPage("study");StackPanel top;studyGrid=Layout(out top);var toolbar=Line();var library=Combo(engine.State.Vocabularies.Cast<object>(),220);library.DisplayMemberPath="Name";library.SelectedItem=engine.Current;library.SelectionChanged+=(s,e)=>{if(library.SelectedItem==null)return;SavePosition();engine.State.CurrentVocabulary=((Vocabulary)library.SelectedItem).Id;DelayedSave();RebuildStudy();};toolbar.Children.Add(library);
   var sort=Combo(new object[]{"固定顺序","随机顺序"},110);sort.SelectedIndex=engine.Position.Mode=="random"?1:0;sort.SelectionChanged+=(s,e)=>{SavePosition();engine.Position.Mode=sort.SelectedIndex==1?"random":"fixed";DelayedSave();RebuildStudy();};toolbar.Children.Add(sort);
   var translation=new CheckBox{Content="显示中文",IsChecked=engine.State.Settings.Translation};translation.Click+=(s,e)=>{engine.State.Settings.Translation=translation.IsChecked==true;foreach(var row in studyRows)AnimateRow(row,()=>{row.Global=engine.State.Settings.Translation;row.Refresh();});DelayedSave();};toolbar.Children.Add(translation);toolbar.Children.Add(Button("搜索",ToggleSearch));top.Children.Add(toolbar);top.Children.Add(Text("点击单词依次查看释义与例句 · ← → 翻页",12,"#79869A"));
   studyColumns=new Grid();studyColumns.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star)});searchColumn=new ColumnDefinition{Width=new GridLength(0)};studyColumns.ColumnDefinitions.Add(searchColumn);
   var left=new Grid();left.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});left.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});studyBody=new ContentControl{HorizontalContentAlignment=HorizontalAlignment.Stretch,VerticalContentAlignment=VerticalAlignment.Stretch};left.Children.Add(studyBody);studyFooter=new StackPanel{Margin=new Thickness(0,12,0,0)};Grid.SetRow(studyFooter,1);left.Children.Add(studyFooter);studyColumns.Children.Add(left);Body(studyGrid,studyColumns);host.Content=studyGrid;
   if(StudyPosition.Anchor==null && engine.Anchor!=null)StudyPosition.Anchor=engine.Anchor;RefreshStudy(false,true);
  }
  void RebuildStudy(){studyScroll=null;ShowStudy();}
  void RefreshStudy(bool animate=false,bool useAnchor=false){var position=StudyPosition;studyPage=WordPage.Build(engine.StudyWords(),engine.State.Reading.StudySize,position,useAnchor);studyRows=studyPage.Words.Select(w=>View(w,"study")).ToList();studyScroll=null;
   studyList=List();VirtualizingPanel.SetIsVirtualizing(studyList,true);VirtualizingPanel.SetVirtualizationMode(studyList,VirtualizationMode.Recycling);ScrollViewer.SetCanContentScroll(studyList,true);studyList.ItemTemplate=(DataTemplate)Window.Resources["WordTemplate"];studyList.ItemsSource=studyRows;studyBody.Content=studyRows.Count>0?(object)studyList:Text("没有待背单词。可在原词书或“更多 → 已掌握词汇”恢复熟词。",18);
   studyFooter.Children.Clear();studyFooter.Children.Add(Pager(studyPage,engine.State.Reading.StudySize,n=>{SavePosition();WordPage.Jump(position,n,studyPage.TotalPages);RefreshStudy(true);DelayedSave();},n=>{SavePosition();engine.State.Reading.StudySize=n;RefreshStudy(true,true);DelayedSave();}));
   restoring=true;var expected=studyList;studyList.Loaded+=(s,e)=>{if(studyList!=expected)return;studyScroll=Child<ScrollViewer>(studyList);if(studyScroll!=null){studyScroll.ScrollToVerticalOffset(studyPage.Offset);studyScroll.ScrollChanged+=(sender,args)=>{if(!restoring&&args.VerticalChange!=0){SavePosition();DelayedSave();}};}Window.Dispatcher.BeginInvoke(DispatcherPriority.ContextIdle,new Action(()=>{if(studyList==expected){restoring=false;SavePosition();}}));};
   if(studyRows.Count==0)restoring=false;if(animate){Slide(studyBody,12);Fade(studyFooter);}DelayedSave();
  }
  void SavePosition(){if(page!="study"||studyRows==null||studyRows.Count==0||studyScroll==null||restoring)return;int index=Math.Min(studyRows.Count-1,Math.Max(0,(int)Math.Floor(studyScroll.VerticalOffset)));var p=StudyPosition;p.Anchor=studyRows[index].Word.Id;p.InPageOffset=index;p.Page=studyPage.Page;engine.SetAnchor(p.Anchor);unsaved=true;}
  FrameworkElement Pager(WordPage data,int size,Action<int> jump,Action<int> resize){var panel=new WrapPanel{VerticalAlignment=VerticalAlignment.Center};var prev=Button("上一页",()=>jump(data.Page-1));prev.IsEnabled=data.Page>1;panel.Children.Add(prev);panel.Children.Add(Text("第 "+data.Page+" / "+data.TotalPages+" 页 · "+data.TotalWords+" 词",12));var next=Button("下一页",()=>jump(data.Page+1));next.IsEnabled=data.Page<data.TotalPages;panel.Children.Add(next);
   var input=new TextBox{Text=data.Page.ToString(),Width=48,MaxLength=6,Margin=new Thickness(0,0,6,0),ToolTip="输入页码",Tag="page-input"};panel.Children.Add(input);Action go=()=>{int n;if(!Int32.TryParse(input.Text,out n)||n<1||n>data.TotalPages){input.BorderBrush=Brushes.IndianRed;input.ToolTip="页码需在 1–"+data.TotalPages+" 之间";return;}jump(n);};input.KeyDown+=(s,e)=>{if(e.Key==Key.Enter){go();e.Handled=true;}};panel.Children.Add(Button("跳转",go));var count=Combo(new object[]{10,20,30,50},65);if(!count.Items.Contains(size))count.Items.Add(size);count.SelectedItem=size;count.ToolTip="每页词数";count.Tag="page-size";count.SelectionChanged+=(s,e)=>{if(count.SelectedItem!=null)resize((int)count.SelectedItem);};panel.Children.Add(count);return panel;
  }
  void StudyKeys(object sender,KeyEventArgs e){if(page!="study"||studyPage==null||(e.Key!=Key.Left&&e.Key!=Key.Right)||Keyboard.Modifiers!=ModifierKeys.None)return;var focus=Keyboard.FocusedElement as DependencyObject;for(var x=focus;x!=null;x=VisualParent(x))if(x is TextBoxBase||x is PasswordBox||x is ComboBox)return;int next=studyPage.Page+(e.Key==Key.Right?1:-1);if(next>=1&&next<=studyPage.TotalPages){SavePosition();WordPage.Jump(StudyPosition,next,studyPage.TotalPages);RefreshStudy(true);DelayedSave();}e.Handled=true;}
  static DependencyObject VisualParent(DependencyObject x){return x is Visual || x is System.Windows.Media.Media3D.Visual3D?VisualTreeHelper.GetParent(x):LogicalTreeHelper.GetParent(x);}
  void ShowBooks(){EnterPage("books");bookMode="";var panel=new StackPanel{Margin=new Thickness(12)};panel.Children.Add(Text("单词本",24));panel.Children.Add(Text("从原词书查看，从收藏继续学习，从已记诵回顾。",14,"#79869A"));panel.Children.Add(Button("原词书",()=>ShowBookPage("original"),true));panel.Children.Add(Text(engine.OriginalWords().Count+" 词 · 固定原始顺序",12,"#79869A"));panel.Children.Add(Button("收藏词本",()=>ShowBookPage("favorites")));panel.Children.Add(Text("默认收藏与自定义单词本",12,"#79869A"));panel.Children.Add(Button("已记诵词本",()=>ShowBookPage("recited")));panel.Children.Add(Text("当前熟词或最近一次默写正确",12,"#79869A"));host.Content=panel;}
  string BookKey {get{return bookMode=="favorites"?"book:"+selectedBook:bookMode=="recited"?"recited:"+engine.State.Reading.RecitedFilter+":"+engine.State.Reading.RecitedSort:"original";}}
  int BookSize {get{return bookMode=="favorites"?engine.State.Reading.FavoriteSize:bookMode=="recited"?engine.State.Reading.RecitedSize:engine.State.Reading.OriginalSize;}}
  void ShowBookPage(string mode){EnterPage("books");bookMode=mode;StackPanel top;var g=Layout(out top);var title=Line();title.Children.Add(Button("返回单词本",ShowBooks));title.Children.Add(Text(mode=="original"?"原词书":mode=="favorites"?"收藏词本":"已记诵词本",23));top.Children.Add(title);
   if(mode=="favorites")BuildFavoriteToolbar(top);
   if(mode=="recited"){var row=Line();var filter=Combo(new object[]{"全部","默写正确","主动标记熟词"},180);filter.SelectedIndex=engine.State.Reading.RecitedFilter=="correct"?1:engine.State.Reading.RecitedFilter=="mastered"?2:0;filter.SelectionChanged+=(s,e)=>{engine.State.Reading.RecitedFilter=new[]{"all","correct","mastered"}[filter.SelectedIndex];DelayedSave();RefreshBookRows();};row.Children.Add(filter);var sort=Combo(new object[]{"最近记诵成功","词库原始顺序"},180);sort.SelectedIndex=engine.State.Reading.RecitedSort=="original"?1:0;sort.SelectionChanged+=(s,e)=>{engine.State.Reading.RecitedSort=sort.SelectedIndex==1?"original":"recent";DelayedSave();RefreshBookRows();};row.Children.Add(sort);top.Children.Add(row);}
   var body=new Grid();body.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});body.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});bookBody=new ContentControl{HorizontalContentAlignment=HorizontalAlignment.Stretch,VerticalContentAlignment=VerticalAlignment.Stretch};body.Children.Add(bookBody);bookFooter=new StackPanel{Margin=new Thickness(0,12,0,0)};Grid.SetRow(bookFooter,1);body.Children.Add(bookFooter);Body(g,body);host.Content=g;RefreshBookRows();
  }
  void BuildFavoriteToolbar(StackPanel top){if(!engine.State.Notebooks.Any(n=>n.Id==selectedBook))selectedBook="default";var row=Line();bookSelect=Combo(engine.State.Notebooks.Cast<object>(),200);bookSelect.DisplayMemberPath="Name";bookSelect.SelectedItem=engine.State.Notebooks.Single(n=>n.Id==selectedBook);bookSelect.SelectionChanged+=(s,e)=>{if(bookSelect.SelectedItem==null)return;selectedBook=((Notebook)bookSelect.SelectedItem).Id;RefreshBookRows();};row.Children.Add(bookSelect);
   row.Children.Add(Button("新建",()=>{var name=Prompt("新建单词本","单词本名称","");if(name!=null){selectedBook=engine.AddNotebook(name).Id;DelayedSave();ShowBookPage("favorites");}}));row.Children.Add(Button("重命名",()=>{var b=(Notebook)bookSelect.SelectedItem;var name=Prompt("重命名单词本","新名称",b.Name);if(name!=null){engine.RenameNotebook(b,name);DelayedSave();ShowBookPage("favorites");}}));row.Children.Add(Button("删除",()=>{var b=(Notebook)bookSelect.SelectedItem;if(b.Id=="default")throw new ArgumentException("默认收藏不能删除。");if(MessageBox.Show(Window,"删除“"+b.Name+"”？词条及学习记录保留。","删除单词本",MessageBoxButton.YesNo)==MessageBoxResult.Yes){engine.DeleteNotebook(b);selectedBook="default";DelayedSave();ShowBookPage("favorites");}}));top.Children.Add(row);
   row=Line();var target=Combo(engine.State.Notebooks.Cast<object>(),180);target.DisplayMemberPath="Name";row.Children.Add(target);row.Children.Add(Button("加入所选词",()=>{var selected=bookList.SelectedItems.Cast<WordView>().ToList();if(selected.Count==0)throw new ArgumentException("请先选择单词，可按 Ctrl 多选。");foreach(var w in selected)engine.PutInNotebook((Notebook)target.SelectedItem,w.Word.Id);DelayedSave();RefreshBookRows();}));row.Children.Add(Button("移出当前词本",()=>{var b=(Notebook)bookSelect.SelectedItem;foreach(var w in bookList.SelectedItems.Cast<WordView>().ToList())b.Words.Remove(w.Word.Id);DelayedSave();RefreshBookRows();}));top.Children.Add(row);
  }
  void RefreshBookRows(){if(bookBody==null||page!="books"||bookMode=="")return;var words=bookMode=="original"?engine.OriginalWords():bookMode=="recited"?engine.Recited(engine.State.Reading.RecitedFilter,engine.State.Reading.RecitedSort):engine.State.Notebooks.Single(n=>n.Id==selectedBook).Words.Select(engine.Find).ToList();var position=engine.ReadingAt(BookKey);bookPage=WordPage.Build(words,BookSize,position,false);var evidence=engine.EvidenceMap();
   var previous=bookList==null?new Dictionary<string,WordView>():bookList.Items.OfType<WordView>().Where(r=>r.Context==bookMode&&r.Engine==engine).ToDictionary(r=>r.Word.Id);var rows=bookPage.Words.Select(w=>{WordView r;if(!previous.TryGetValue(w.Id,out r))r=View(w,bookMode);RecitationEvidence e;var labels=new List<string>();if(engine.Favorite(w.Id))labels.Add("收藏");Progress p;if(engine.State.Progress.TryGetValue(w.Id,out p)&&p.LearnedAt>0)labels.Add("已学习");if(evidence.TryGetValue(w.Id,out e)){if(e.Mastered)labels.Add("熟词");if(e.Mastered||e.LastCorrect==true)labels.Add("已记诵");}r.StatusLabel=String.Join(" · ",labels);r.Refresh();return r;}).ToList();bookList=List();bookList.SelectionMode=SelectionMode.Extended;bookList.ItemTemplate=(DataTemplate)Window.Resources["WordTemplate"];bookList.ItemsSource=rows;bookBody.Content=rows.Count>0?(object)bookList:Text("这里还没有单词。",18);bookFooter.Children.Clear();bookFooter.Children.Add(Pager(bookPage,BookSize,n=>{WordPage.Jump(position,n,bookPage.TotalPages);RefreshBookRows();Fade(bookFooter);Slide(bookBody,12);DelayedSave();},n=>{if(bookMode=="original")engine.State.Reading.OriginalSize=n;else if(bookMode=="favorites")engine.State.Reading.FavoriteSize=n;else engine.State.Reading.RecitedSize=n;position.Page=1;RefreshBookRows();DelayedSave();}));
  }
  void ToggleSearch(){if(searchPanel!=null){CloseSearch();return;}searchColumn.Width=new GridLength(Math.Min(350,Math.Max(280,studyColumns.ActualWidth*.42)));searchPanel=new Border{Background=Brushes.White,BorderBrush=(Brush)new BrushConverter().ConvertFromString("#DEE7F3"),BorderThickness=new Thickness(1),CornerRadius=new CornerRadius(12),Margin=new Thickness(12,0,0,0),Padding=new Thickness(12)};Grid.SetColumn(searchPanel,1);var panel=searchPanel;var g=new Grid();g.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});g.RowDefinitions.Add(new RowDefinition{Height=new GridLength(145)});g.RowDefinitions.Add(new RowDefinition{Height=new GridLength(1,GridUnitType.Star)});
   var top=new StackPanel();var heading=new DockPanel{Margin=new Thickness(0,0,0,12)};var close=Button("关闭",CloseSearch);DockPanel.SetDock(close,Dock.Right);heading.Children.Add(close);heading.Children.Add(Text("英文全库搜索",16));top.Children.Add(heading);var query=new TextBox{Tag="search-input",ToolTip="输入英文单词或部分字母"};top.Children.Add(query);g.Children.Add(top);var results=List();results.DisplayMemberPath="English";Grid.SetRow(results,1);g.Children.Add(results);var details=new ScrollViewer{VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetRow(details,2);g.Children.Add(details);results.SelectionChanged+=(s,e)=>{var w=results.SelectedItem as Word;if(w!=null)details.Content=new ContentControl{Content=new WordView{Word=w,Engine=engine,Context="search",Global=true,Level=2},ContentTemplate=(DataTemplate)Window.Resources["WordTemplate"]};};query.TextChanged+=(s,e)=>{results.ItemsSource=engine.SearchEnglish(query.Text);details.Content=null;};panel.Child=g;studyColumns.Children.Add(panel);Slide(panel,40);query.Focus();}
  void CloseSearch(){if(searchPanel==null)return;var panel=searchPanel;var owner=studyColumns;var column=searchColumn;searchPanel=null;SlideOut(panel,()=>{owner.Children.Remove(panel);if(searchPanel==null&&studyColumns==owner)column.Width=new GridLength(0);});}
 }
